%[text] # FLARE：Learned/Transfer × hM4D(Gi)/Others 的 NTATS 热图
%[text] 输出：SVG + PNG(300dpi)
% 注意：请先在 MATLAB 中打开工程（Transferlearning.prj）以加载必要路径。

outDir = "\\Data-Server-2\个人数据\张天夫\202512";
if ~exist(outDir, 'dir')
	mkdir(outDir);
end
%%
%[text] ## 1) 载入 FLARE 数据
F = TransferLearning.scFLARE; %[output:360a726e] %[output:269bff9d] %[output:21313499] %[output:6bb1d824] %[output:20d10bae] %[output:3ff10d7a] %[output:3e8b0edf] %[output:39209dbf] %[output:22368934] %[output:65115599] %[output:5e08476d] %[output:9d499f3c] %[output:257286e2] %[output:6cd6f05f] %[output:85a48bbc]
%%
%[text] ## 2) 查询 Learned→Final 的所有会话 NTATS（每会话一列）
% 口径：以 DateTime 为准，取从 Learned 会话到 Final 会话（含）之间的所有会话。
% 注意：Transfer~Final 之间 Phase 可能为 <missing>，这些会话也必须画出来（不忽略）。
% 每个会话的 Stimulus 按其 DateTime 对应的 Blocks/Trials 中出现最多的 Stimulus 自动推断。

DT = F.DateTimes;
B = F.Blocks;
T = F.Trials;

phaseAll = string(DT.Phase);

idxLearnedDT = find(phaseAll == "Learned", 1, 'first');
idxFinalDT = find(phaseAll == "Final", 1, 'first');
if isempty(idxLearnedDT) || isempty(idxFinalDT)
	error('Cannot find Learned/Final in F.DateTimes.Phase.');
end

dtStart = DT.DateTime(idxLearnedDT);
dtEnd = DT.DateTime(idxFinalDT);
if dtEnd < dtStart
	error('Final DateTime is earlier than Learned DateTime.');
end

Sess = DT(DT.DateTime >= dtStart & DT.DateTime <= dtEnd, {'DateTime','Phase'});
Sess.Phase = string(Sess.Phase);
Sess = sortrows(Sess, 'DateTime');

stimulus = strings(height(Sess), 1);
for i = 1:height(Sess)
	dt = Sess.DateTime(i);
	blockUIDs = B.BlockUID(B.DateTime == dt);
	st = string(T.Stimulus(ismember(T.BlockUID, blockUIDs)));
	st = st(~ismissing(st));
	if isempty(st)
		stimulus(i) = missing;
	else
		[u, ~, ic] = unique(st);
		c = accumarray(ic, 1);
		[~, m] = max(c);
		stimulus(i) = u(m);
	end
end

QueryTable = table();
phaseLabel = Sess.Phase;
phaseLabel(ismissing(phaseLabel)) = "Missing";
QueryTable.GroupName = phaseLabel + "_" + string(Sess.DateTime, 'yyyyMMdd_HHmm');
QueryTable.DateTime = Sess.DateTime;
QueryTable.Phase = Sess.Phase;
QueryTable.Stimulus = stimulus;

% 分组名称（会话列表）：严格按 DateTime 升序，从左到右
groupNames = string(QueryTable.GroupName(:))';

% 细胞排序与行对齐口径：以 Learned 会话为准（同一横行永远对应同一个 CellUID）
idxLearned = find(string(QueryTable.Phase) == "Learned", 1, 'first');
if isempty(idxLearned)
	error('Cannot find a Learned session in the selected DateTime range.');
end

learnedGroupName = string(QueryTable.GroupName(idxLearned));
LearnedNtats = F.QueryNTATS(QueryTable(idxLearned, :), UniExp.Flags.ZScore, 1:24, UniExp.Flags.Median); %[output:0d3217b1]

cellUIDAll = LearnedNtats.CellUID;
learnedData = LearnedNtats.NTATS{:,:, learnedGroupName};
learnedData = squeeze(learnedData);
if ~ismatrix(learnedData)
	error('Unexpected Learned NTATS dimension.');
end

nCells = numel(cellUIDAll);
nTime = size(learnedData, 2);
nSess = height(QueryTable);

% DataAll: (cell x time x session)，会话无数据时保留 NaN（不忽略该列）
DataAll = nan(nCells, nTime, nSess);
DataAll(:, :, idxLearned) = learnedData;

for i = 1:nSess
	if i == idxLearned
		continue;
	end
	if ismissing(QueryTable.Stimulus(i))
		continue;
	end
	try
		Gi = F.QueryNTATS(QueryTable(i, :), UniExp.Flags.ZScore, 1:24, UniExp.Flags.Median);
	catch ME
		if contains(ME.message, 'UniExp:Exception:Empty_group')
			continue;
		end
		rethrow(ME);
	end

	datai = Gi.NTATS{:,:, string(QueryTable.GroupName(i))};
	datai = squeeze(datai);
	if ~ismatrix(datai)
		error('Unexpected NTATS dimension for %s.', string(QueryTable.GroupName(i)));
	end

	[tf, loc] = ismember(Gi.CellUID, cellUIDAll);
	DataAll(loc(tf), :, i) = datai(tf, :);
end
%%
%[text] ## 3) 按 hM4D(Gi) vs Others × 2/3 vs 5 层 分组
hm4dUID = F.Cells.CellUID(F.Cells.CellType == "hM4D(Gi)");

[tfCell, locCell] = ismember(cellUIDAll, F.Cells.CellUID);
if ~all(tfCell)
	missingN = nnz(~tfCell);
	error('Some CellUID are missing from F.Cells (n=%d).', missingN);
end

cellTypeAll = string(F.Cells.CellType(locCell));
zLayerAll = string(F.Cells.ZLayer(locCell));

maskHm4d = (cellTypeAll == "hM4D(Gi)");
maskOther = (cellTypeAll == "Others");
maskMOp23 = (zLayerAll == "MOp2/3");
maskMOp5 = (zLayerAll == "MOp5");

Ntats_Hm4d_MOp23 = GroupNtats(maskHm4d & maskMOp23, :);
Ntats_Hm4d_MOp5  = GroupNtats(maskHm4d & maskMOp5,  :);
Ntats_Other_MOp23 = GroupNtats(maskOther & maskMOp23, :);
Ntats_Other_MOp5  = GroupNtats(maskOther & maskMOp5,  :);
%%
%[text] ## 4) 排序并绘制 4×N 热图（4 行：细胞类型×层；N 列：会话）
% 每个子图行内的排序均以 Learned 列为准；各列严格按 DateTime 从左到右。

uid_Hm4d_MOp23 = cellUIDAll(maskHm4d & maskMOp23);
uid_Hm4d_MOp5  = cellUIDAll(maskHm4d & maskMOp5);
uid_Other_MOp23 = cellUIDAll(maskOther & maskMOp23);
uid_Other_MOp5  = cellUIDAll(maskOther & maskMOp5);

Data_Hm4d_MOp23 = iDataSortedByLearned(LearnedNtats, learnedGroupName, uid_Hm4d_MOp23, cellUIDAll, DataAll);
Data_Hm4d_MOp5  = iDataSortedByLearned(LearnedNtats, learnedGroupName, uid_Hm4d_MOp5,  cellUIDAll, DataAll);
Data_Other_MOp23 = iDataSortedByLearned(LearnedNtats, learnedGroupName, uid_Other_MOp23, cellUIDAll, DataAll);
Data_Other_MOp5  = iDataSortedByLearned(LearnedNtats, learnedGroupName, uid_Other_MOp5,  cellUIDAll, DataAll);

% 计算并传入 LanearHeatmap 的 CLim（带符号平方根变换）
allData = cat(1, Data_Hm4d_MOp23, Data_Hm4d_MOp5, Data_Other_MOp23, Data_Other_MOp5);
oldNeg = min(allData, [], 'all', 'omitnan');
oldPos = max(allData, [], 'all', 'omitnan');
sqrtCLim = [ -sqrt(abs(oldNeg)), sqrt(abs(oldPos)) ];

Fig = figure; %[output:77a4ec67]
Layout = tiledlayout(4, numel(groupNames), TileSpacing='compact', Padding='tight'); %[output:77a4ec67]

% 显示风格
CommonFlags = [UniExp.Flags.HideYAxis, UniExp.Flags.SymmetricColormap];

% 每行 2 张：Learned / Transfer
Axes_Hm4d_MOp23 = iLanearHeatmapAxes(Layout, Data_Hm4d_MOp23, CommonFlags, sqrtCLim); %[output:77a4ec67]
Axes_Hm4d_MOp5  = iLanearHeatmapAxes(Layout, Data_Hm4d_MOp5,  CommonFlags, sqrtCLim); %[output:77a4ec67]
Axes_Other_MOp23 = iLanearHeatmapAxes(Layout, Data_Other_MOp23, CommonFlags, sqrtCLim); %[output:77a4ec67]
Axes_Other_MOp5  = iLanearHeatmapAxes(Layout, Data_Other_MOp5,  CommonFlags, sqrtCLim); %[output:77a4ec67]

AxesAll = [Axes_Hm4d_MOp23(:); Axes_Hm4d_MOp5(:); Axes_Other_MOp23(:); Axes_Other_MOp5(:)];
AxesAll = AxesAll(isgraphics(AxesAll));

% 关闭 toolbar，避免导出 SVG 时混入 UI
for k = 1:numel(AxesAll)
	try
		axtoolbar(AxesAll(k), 'Visible', 'off'); %[output:77a4ec67]
	catch
	end
end

% 标题、参考线
AxesRows = {Axes_Hm4d_MOp23, Axes_Hm4d_MOp5, Axes_Other_MOp23, Axes_Other_MOp5};
for r = 1:numel(AxesRows)
	axRow = AxesRows{r};
	for k = 1:numel(axRow)
		if r == 1 && k <= numel(groupNames)
			title(axRow(k), groupNames(k), Interpreter='none'); %[output:77a4ec67]
		end
		xline(axRow(k), 0, ':k');
		xline(axRow(k), 1, '-k');
	end
end

% 只在每行第一列显示 y 轴并标注细胞数
Axes_Hm4d_MOp23(1).YAxis.Visible = 'on'; %[output:77a4ec67]
Axes_Hm4d_MOp5(1).YAxis.Visible = 'on'; %[output:77a4ec67]
Axes_Other_MOp23(1).YAxis.Visible = 'on'; %[output:77a4ec67]
Axes_Other_MOp5(1).YAxis.Visible = 'on'; %[output:77a4ec67]

ylabel(Axes_Hm4d_MOp23(1), sprintf('hM4D(Gi) MOp2/3 (%u)', height(Ntats_Hm4d_MOp23))); %[output:77a4ec67]
ylabel(Axes_Hm4d_MOp5(1),  sprintf('hM4D(Gi) MOp5 (%u)',  height(Ntats_Hm4d_MOp5)), FontSize=10); %[output:77a4ec67]
ylabel(Axes_Other_MOp23(1), sprintf('Others MOp2/3 (%u)', height(Ntats_Other_MOp23)), FontSize=10); %[output:77a4ec67]
ylabel(Axes_Other_MOp5(1),  sprintf('Others MOp5 (%u)',  height(Ntats_Other_MOp5)), FontSize=10); %[output:77a4ec67]

Axes_Hm4d_MOp23(1).YLabel.FontSize = 10; %[output:77a4ec67]

xlabel(Layout, 'Time(s) from cue(:) water(|)'); %[output:77a4ec67]

CB = colorbar; %[output:77a4ec67]
CB.Layout.Tile = 'east'; %[output:77a4ec67]
CB.Label.String = 'z-score'; %[output:77a4ec67]

% 尽量保持紧凑的版式
try %[output:group:35b9ab20]
	MATLAB.Graphics.FigureAspectRatio(max(2, numel(groupNames)), 4, MATLAB.Flags.Amplify); %[output:77a4ec67]
catch
end %[output:group:35b9ab20]
%%
%[text] ## 5) 导出
baseName = "FLARE hM4D(Gi)与Others细胞NTATS热图";
svgPath = fullfile(outDir, baseName + ".svg");
pngPath = fullfile(outDir, baseName + ".png");

print(Fig, svgPath, '-dsvg'); %[output:848a011f]
exportgraphics(Fig, pngPath, 'Resolution', 300); %[output:848a011f]

fprintf('Saved:\n  %s\n  %s\n', svgPath, pngPath); %[output:3e1abacc]


function Ax = iLanearHeatmapAxes(Layout, Data, CommonFlags, sqrtCLim)
[~, Ax] = UniExp.LanearHeatmap( ...
	Data, ...
	XData=seconds([-3,3]), ...
	Flags=CommonFlags, ...
	CLim=sqrtCLim, ...
	Layout=Layout ...
);

Ax = Ax(isgraphics(Ax));
if ~isempty(Ax)
	tiles = arrayfun(@(a)a.Layout.Tile, Ax);
	[~, idx] = sort(tiles);
	Ax = Ax(idx);
end
end

